export const ASSETS = {"/":"<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>مِضمار – لوحة المعلمة</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><div id=\"app\"></div><script src=\"/admin.js\"></script></body></html>\n","/index.html":"<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>مِضمار – لوحة المعلمة</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><div id=\"app\"></div><script src=\"/admin.js\"></script></body></html>\n","/admin.js":"const $=(s,r=document)=>r.querySelector(s),app=$('#app');\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nasync function api(u,m='GET',b){const r=await fetch(u,{method:m,headers:b?{'Content-Type':'application/json'}:{},body:b?JSON.stringify(b):undefined});\n const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'حدث خطأ');return j}\nfunction toast(t){const e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),2500)}\nfunction confirmBox(msg){return new Promise(res=>{const d=document.createElement('dialog');d.innerHTML=`<p>${esc(msg)}</p><div class=row><button class=\"btn d\" value=y>نعم، تأكيد</button><button class=btn value=n>إلغاء</button></div>`;\n document.body.append(d);d.showModal();d.onclick=e=>{if(e.target.value){d.close();d.remove();res(e.target.value==='y')}}})}\nlet me=null;\nasync function loginScreen(){\n const error=new URLSearchParams(location.search).get('auth_error');\n const message=error==='not_configured'?'تسجيل Google غير مهيأ في إعدادات الخادم.':error?'تعذر تسجيل الدخول عبر Google. حاول مرة أخرى.':'';\n app.innerHTML=`<main class=\"center\"><section class=\"card narrow login-card\"><h1>مِضمار</h1><p>سجّل الدخول بحساب Google لعرض مسابقاتك وأعمالك الخاصة.</p>${message?`<p class=\"err\">${esc(message)}</p>`:''}<a class=\"btn p google-login\" href=\"/auth/google\"><span aria-hidden=\"true\">G</span> تسجيل الدخول باستخدام Google</a><small>كل حساب له مساحة خاصة لا يطلع عليها الآخرون.</small></section></main>`;\n}\nlet onboardingState=null;\nconst tourSteps=[\n {title:'الرئيسية',text:'هنا تتابع عدد مسابقاتك والمجموعات المشاركة ومتوسط الدرجات وأعلى نتيجة.'},\n {title:'المسابقات',text:'من صفحة المسابقات تدير اختباراتك، وتفتح النتائج، وتعدّل المسابقة أو تنسخها أو تؤرشفها.'},\n {title:'إنشاء مسابقة',text:'أنشئ مسابقة جديدة، أضف الأسئلة والخيارات وحدد الإجابة الصحيحة والوقت وطريقة المشاركة.'},\n {title:'لوحة العرض ورمز الدخول',text:'ابدأ المسابقة وافتح لوحة العرض. شارك رمز الدخول أو رمز QR مع الطلاب للانضمام.'},\n {title:'النتائج والتقارير',text:'تابع ترتيب المجموعات والدرجات والإحصاءات، ويمكنك تصدير النتائج عند توفرها.'},\n {title:'الإعدادات',text:'راجع الحساب، ويمكنك الرجوع إلى هذا الشرح لاحقًا من صفحة الإعدادات.'}\n];\nasync function finishOnboarding(){await api('/api/onboarding/complete','POST');onboardingState={version:2,showTutorial:false,showUpdateNotice:false}}\nfunction showTour(){\n let i=0;const d=document.createElement('dialog');d.className='brand-dialog';\n const draw=()=>{const x=tourSteps[i];d.innerHTML=`<div class=\"brand-card\" style=\"display:block\"><small>دليل مِضمار · ${i+1} من ${tourSteps.length}</small><h2>${esc(x.title)}</h2><p>${esc(x.text)}</p><div class=\"row\"><button class=\"btn\" id=\"tourSkip\">تخطي الشرح</button><span class=\"sp\"></span><button class=\"btn p\" id=\"tourNext\">${i===tourSteps.length-1?'إنهاء':'التالي'}</button></div></div>`;\n $('#tourSkip',d).onclick=async()=>{await finishOnboarding();d.close();d.remove()};\n $('#tourNext',d).onclick=async()=>{if(i<tourSteps.length-1){i++;draw()}else{await finishOnboarding();d.close();d.remove();toast('اكتمل الشرح')}}};\n document.body.append(d);draw();d.showModal();\n}\nasync function onboarding(){\n onboardingState=await api('/api/onboarding');\n if(onboardingState.showTutorial){showTour();return}\n if(onboardingState.showUpdateNotice){\n  const d=document.createElement('dialog');d.className='brand-dialog';\n  d.innerHTML='<div class=\"brand-card\" style=\"display:block\"><small>مِضمار 2.0</small><h2>تم تحديث مِضمار</h2><p>أضفنا دليلًا تفاعليًا يشرح أقسام الموقع وطريقة إنشاء المسابقات ومتابعة النتائج. يمكنك بدء الشرح الآن أو تشغيله لاحقًا من الإعدادات.</p><div class=\"row\"><button class=\"btn\" id=\"updateLater\">لاحقًا</button><span class=\"sp\"></span><button class=\"btn p\" id=\"updateStart\">ابدأ الشرح</button></div></div>';\n  document.body.append(d);d.showModal();\n  $('#updateLater',d).onclick=async()=>{await finishOnboarding();d.close();d.remove()};\n  $('#updateStart',d).onclick=()=>{d.close();d.remove();showTour()};\n }\n}\nasync function render(){\n me=await fetch('/api/me').then(r=>r.json()).catch(()=>({authenticated:false}));\n if(!me.authenticated){await loginScreen();return}\n const h=location.hash.slice(1)||'/';const m=h.match(/^\\/quiz\\/(new|\\d+)\\/?(edit|results)?$/);\n app.innerHTML=`<nav class=nav><div class=wrap><b>مِضمار</b><a href=\"#/\" data-p=\"/\">الرئيسية</a><a href=\"#/quizzes\" data-p=\"/quizzes\">المسابقات</a><a href=\"#/settings\" data-p=\"/settings\">الإعدادات</a><span class=sp></span><button class=\"btn nav-logout\" id=\"logoutBtn\" type=\"button\">تسجيل الخروج</button><button class=\"brand-mark\" id=\"brandOpen\" type=\"button\" aria-label=\"عرض بطاقة التطوير\" aria-haspopup=\"dialog\" aria-controls=\"brandDialog\"><span aria-hidden=\"true\">©</span></button><dialog class=\"brand-dialog\" id=\"brandDialog\" aria-labelledby=\"brandTitle\"><div class=\"brand-card\"><img src=\"/entrit-logo.svg\" alt=\"شعار أنتريت\"><div class=\"brand-copy\"><strong id=\"brandTitle\">تطوير أنتريت</strong><span>تم تطوير مِضمار بواسطة أنتريت</span><small id=\"brandVersion\">إصدار الموقع 1.0.0</small></div></div><button class=\"btn brand-close\" id=\"brandClose\" type=\"button\">إغلاق</button></dialog></div></nav><main class=wrap id=main></main>`;\n fetch('/api/version').then(r=>r.json()).then(v=>{const el=$('#brandVersion');if(el)el.textContent='إصدار الموقع '+v.version}).catch(()=>{});\n $('#logoutBtn').onclick=async()=>{await api('/api/logout','POST');me=null;location.hash='/';render()};\n document.querySelectorAll('.nav a[data-p]').forEach(a=>a.classList.toggle('on',a.dataset.p===h));\n const brandDialog=$('#brandDialog');$('#brandOpen').onclick=()=>brandDialog.showModal();$('#brandClose').onclick=()=>brandDialog.close();brandDialog.onclick=e=>{if(e.target===brandDialog)brandDialog.close()};\n const M=$('#main');try{await onboarding();if(h==='/')await home(M);else if(h==='/quizzes')await list(M);else if(h==='/settings')settings(M);\n  else if(m&&m[1]==='new')editor(M,null);else if(m&&m[2]==='results')await results(M,m[1]);else if(m)await editor(M,m[1]);else M.textContent='الصفحة غير موجودة'}catch(e){if(e.message!=='401')M.innerHTML='<p class=err>'+esc(e.message)+'</p>'}}\naddEventListener('hashchange',render);\nconst dur=s=>s>=60?`${Math.floor(s/60)}د ${s%60}ث`:s+'ث';\nfunction chart(d){const W=Math.max(320,d.length*90),mx=Math.max(1,...d.map(x=>x.max));return `<div style=\"overflow-x:auto\"><svg viewBox=\"0 0 ${W} 190\" width=\"${W}\" role=img aria-label=\"متوسط الدرجات لكل مسابقة\">${d.map((x,i)=>{const h=Math.round(120*x.avg/mx),X=i*90+20;\n return `<rect x=${X} y=${140-h} width=50 height=${h} rx=6 fill=\"var(--g)\"/><text x=${X+25} y=${134-h} text-anchor=middle fill=\"var(--ink)\" font-size=13>${x.avg}/${x.max}</text><text x=${X+25} y=165 text-anchor=middle fill=\"var(--mut)\" font-size=12>${esc(x.title.slice(0,10))}</text>`}).join('')}</svg></div>`}\nasync function home(M){const d=await api('/api/dashboard');M.innerHTML=`<h1>الرئيسية</h1><div class=grid>\n <div class=\"card stat\"><b>${d.quizzes}</b><span>إجمالي المسابقات (${d.active} نشطة)</span></div><div class=\"card stat\"><b>${d.groups}</b><span>إجمالي المجموعات المشاركة</span></div>\n <div class=\"card stat\"><b>${d.avg}</b><span>متوسط الدرجات</span></div><div class=\"card stat\"><b>${d.best?esc(d.best.name):'—'}</b><span>${d.best?`أعلى نتيجة: ${d.best.score}/${d.best.total} في «${esc(d.best.quiz)}»`:'لا توجد نتائج بعد'}</span></div></div>\n <div class=card style=\"margin-top:1em\"><h2>متوسط الدرجات حسب المسابقة</h2>${d.chart.length?chart(d.chart):'<p>أنشئي مسابقة لتظهر هنا النتائج.</p>'}</div>\n <div class=card style=\"margin-top:1em\"><h2>آخر المسابقات</h2>${d.recent.map(r=>`<p><a href=\"#/quiz/${r.id}/results\">${esc(r.title)}</a> ${r.archived?'<span class=tag>مؤرشفة</span>':''}</p>`).join('')||'<p>لا توجد مسابقات بعد.</p>'}</div>`}\nlet tab='active';\nasync function list(M){const all=await api('/api/quizzes');const L=all.filter(z=>tab==='active'?!z.archived:z.archived);\n M.innerHTML=`<div class=row><h1 class=sp>المسابقات</h1><button class=\"btn ${tab==='active'?'p':''}\" data-t=active>النشطة</button><button class=\"btn ${tab==='arch'?'p':''}\" data-t=arch>السابقة (المؤرشفة)</button></div>\n ${L.map(z=>`<div class=card style=\"margin:.7em 0\"><div class=row><div class=sp><h3 style=\"margin:0\">${esc(z.title)}</h3><small style=\"color:var(--mut)\">${z.nq} سؤال · ${z.ng} مجموعة · الرمز ${z.code}</small></div>\n <a class=\"btn p\" target=_blank href=\"/board/${z.code}\">ابدأ المسابقة</a><a class=\"btn s\" href=\"#/quiz/${z.id}/results\">النتائج</a><a class=\"btn s\" href=\"#/quiz/${z.id}/edit\">تعديل</a>\n <button class=\"btn s\" data-a=copy data-id=${z.id}>نسخ</button><button class=\"btn s\" data-a=arch data-id=${z.id}>${z.archived?'إلغاء الأرشفة':'أرشفة'}</button><button class=\"btn s d\" data-a=del data-id=${z.id}>حذف</button></div></div>`).join('')||'<p>لا توجد مسابقات هنا.</p>'}<div class=card style=\"margin-top:1em;text-align:center\"><h3>ابدأ اختبارًا جديدًا</h3><p>أنشئ مسابقة وحدد طريقة المشاركة ثم أضف الأسئلة.</p><a class=\"btn p\" href=\"#/quiz/new\">+ إنشاء مسابقة</a></div>`;\n M.onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.t){tab=b.dataset.t;return list(M)}const id=b.dataset.id,z=all.find(x=>x.id==id);\n  if(b.dataset.a==='copy'){await api(`/api/quizzes/${id}/copy`,'POST');toast('تم النسخ');list(M)}\n  if(b.dataset.a==='arch'){await api(`/api/quizzes/${id}/archive`,'POST');list(M)}\n  if(b.dataset.a==='del'&&await confirmBox(`حذف «${z.title}» ونتائجها نهائيًا؟`)){await api('/api/quizzes/'+id,'DELETE');toast('تم الحذف');list(M)}\n  if(b.dataset.a==='share')share(z)}}\nfunction share(z){const url=`${location.origin}/j/${z.code}`,d=document.createElement('dialog');d.innerHTML=`<h3>${esc(z.title)}</h3><img alt=\"QR\" src=\"/api/qr?text=${encodeURIComponent(url)}\" width=220 height=220 style=\"display:block;margin:auto;background:#fff\"><p>رمز الدخول: <b style=\"font-size:1.4em\">${z.code}</b></p><input readonly value=\"${url}\" onfocus=this.select()><div class=row style=\"margin-top:.7em\"><button class=\"btn p\" id=cp>نسخ الرابط</button><button class=btn id=cl>إغلاق</button></div>`;\n document.body.append(d);d.showModal();$('#cp',d).onclick=()=>navigator.clipboard.writeText(url).then(()=>toast('تم النسخ'));$('#cl',d).onclick=()=>{d.close();d.remove()}}\nasync function settings(M){const d=await api('/api/me');M.innerHTML=`<h1>الإعدادات</h1><div class=card style=\"max-width:520px\"><h2>حسابك</h2><p><b>البريد الإلكتروني:</b> ${esc(d.email||'—')}</p><p><b>طريقة الدخول:</b> Google</p><p style=\"color:var(--mut)\">بيانات المسابقات محفوظة في مساحة حسابك الخاصة.</p></div><hr><h2>المساعدة</h2><p>يمكنك إعادة مشاهدة شرح مِضمار في أي وقت.</p><button class=\"btn p\" id=\"replayTour\">إعادة شرح الموقع</button>`;$('#replayTour').onclick=showTour}\nconst toMs=v=>v?new Date(v).getTime():null,fromMs=v=>v?new Date(v-new Date().getTimezoneOffset()*6e4).toISOString().slice(0,16):'';\nconst readImg=f=>new Promise((res,rej)=>{if(!f)return res('');if(f.size>1.5e6)return rej(Error('الصورة كبيرة (الحد 1.5 ميغابايت)'));const r=new FileReader();r.onload=()=>res(r.result);r.readAsDataURL(f)});\nasync function editor(M,id){\n const z=id?await api('/api/quizzes/'+id):{title:'',description:'',image:'',time_limit:0,shuffle_q:0,shuffle_a:0,show_correct:1,allow_retry:0,start_at:null,end_at:null,participation_mode:'groups',entry_mode:'both',progression_mode:'sequential',roster:'',questions:[],ng:0};\n const locked=id&&(await api('/api/quizzes')).find(x=>x.id==id).ng>0;let Q=z.questions.map(x=>({...x})),step=0;\n const ck=(k,t)=>`<label style=\"display:flex;gap:.5em;align-items:center;font-weight:400\"><input type=checkbox id=${k} style=\"width:auto\" ${z[k]?'checked':''}>${t}</label>`;\n M.innerHTML=`<div class=row><h1 class=sp>${id?'تعديل المسابقة':'إنشاء مسابقة جديدة'}</h1><a class=btn href=\"#/quizzes\">رجوع</a></div><div class=card>\n <div class=row id=steps><span class=tag>1 · بيانات المسابقة</span><span class=tag>2 · المشاركة</span><span class=tag>3 · الأسئلة</span></div>\n <section data-step=0><h2>بيانات المسابقة</h2><label>اسم المسابقة</label><input id=title value=\"${esc(z.title)}\"><label>الوصف / التعليمات</label><textarea id=desc rows=3>${esc(z.description)}</textarea>\n <label>صورة المسابقة</label><input type=file id=img accept=\"image/*\"><div id=coverPreview>${z.image?`<img src=\"${z.image}\" style=\"max-height:100px\">`:''}</div>\n <div class=grid><div><label>المدة بالدقائق (0 بلا حد)</label><input type=number min=0 id=tl value=${z.time_limit}></div><div><label>موعد البدء</label><input type=datetime-local id=sa value=\"${fromMs(z.start_at)}\"></div><div><label>موعد الإغلاق</label><input type=datetime-local id=ea value=\"${fromMs(z.end_at)}\"></div></div>\n <hr><h3>إعدادات عرض الأسئلة</h3>${ck('shuffle_q','ترتيب الأسئلة عشوائي')}${ck('shuffle_a','ترتيب الإجابات عشوائي')}${ck('show_correct','إظهار الإجابة الصحيحة')}${ck('allow_retry','السماح بإعادة المحاولة')}</section>\n <section data-step=1 hidden><h2>طريقة المشاركة</h2><label>نوع المشاركة</label><select id=participation_mode><option value=groups ${z.participation_mode!=='students'?'selected':''}>مجموعات – جهاز لكل مجموعة</option><option value=students ${z.participation_mode==='students'?'selected':''}>طلاب – كل طالب بجهازه</option></select>\n <label>طريقة التسجيل</label><select id=entry_mode><option value=both ${!z.entry_mode||z.entry_mode==='both'?'selected':''}>قائمة المعلم أو تسجيل ذاتي</option><option value=qr ${z.entry_mode==='qr'?'selected':''}>QR أو الرابط</option><option value=roster ${z.entry_mode==='roster'?'selected':''}>قائمة المعلم فقط</option></select>\n <label>أسماء الطلاب (اسم في كل سطر)</label><textarea id=roster rows=5>${esc(z.roster||'')}</textarea>\n <label>طريقة الانتقال بين الأسئلة</label><select id=progression_mode><option value=sequential ${!z.progression_mode||z.progression_mode==='sequential'?'selected':''}>تسلسلي</option><option value=free ${z.progression_mode==='free'?'selected':''}>حر</option><option value=teacher ${z.progression_mode==='teacher'?'selected':''}>تحكم المعلم</option></select></section>\n <section data-step=2 hidden><h2>الأسئلة</h2><div class=card><h3>إنشاء الأسئلة من صورة</h3><input type=file id=sheet accept=\"image/*\"><button class=btn id=readSheet type=button>قراءة الورقة بالذكاء الاصطناعي</button><small id=aiStatus>ترفع الصورة ثم راجع الأسئلة المستخرجة قبل اعتمادها.</small></div>\n <div id=qs></div>${locked?'':'<div class=row><button class=btn id=addmc>+ اختيار متعدد</button><button class=btn id=addtf>+ صح أو خطأ</button><button class=btn id=addorder>+ رتّب العناصر</button></div>'}</section>\n <p class=err id=e></p><div class=row style=\"justify-content:space-between;margin-top:1em\"><button class=btn id=prev hidden>السابق</button><span class=sp></span><button class=\"btn p\" id=next>التالي</button><button class=\"btn p\" id=save hidden>إنشاء المسابقة</button></div></div>`;\n const show=()=>{M.querySelectorAll('[data-step]').forEach(x=>x.hidden=+x.dataset.step!==step);M.querySelectorAll('#steps .tag').forEach((x,i)=>x.style.opacity=i===step?'1':'.45');$('#prev').hidden=step===0;$('#next').hidden=step===2;$('#save').hidden=step!==2};show();\n const draw=()=>{$('#qs').innerHTML=Q.map((q,i)=>`<div class=q data-i=${i}><div class=row><b>سؤال ${i+1} · ${q.type==='tf'?'صح أو خطأ':q.type==='order'?'رتّب العناصر':'اختيار متعدد'}</b><span class=sp></span><label>الدرجة <input type=number min=1 data-f=points value=${q.points} style=\"width:4em\"></label>${locked?'':'<button class=\"btn s d\" data-del>حذف</button>'}</div><label>نص السؤال</label><textarea data-f=text>${esc(q.text)}</textarea><label>${q.type==='order'?'العناصر بالترتيب الصحيح':'الخيارات'}</label>${(q.type==='tf'?['صح','خطأ']:q.options).map((o,j)=>`<div class=opt>${q.type==='order'?`<b>${j+1}.</b>`:'<input type=radio name=c'+i+' data-c='+j+(q.correct===j?' checked':'')+'>'}<input data-o=${j} value=\"${esc(o)}\" placeholder=\"عنصر ${j+1}\"><button class=\"btn s\" data-rm=${j} ${q.options.length<=2?'disabled':''}>×</button></div>`).join('')}${q.type!=='tf'&&q.options.length<6&&!locked?'<button class=btn data-addo>+ خيار</button>':''}</div>`).join('')||'<p>أضف سؤالًا من الأزرار.</p>';};\n draw();const box=$('#qs');\n box.oninput=e=>{const el=e.target.closest('.q');if(!el)return;const q=Q[+el.dataset.i],t=e.target;if(t.dataset.f)q[t.dataset.f]=t.dataset.f==='points'?+t.value:t.value;if(t.dataset.o!==undefined)q.options[+t.dataset.o]=t.value};\n box.onchange=async e=>{const el=e.target.closest('.q');if(el&&e.target.dataset.c!==undefined)Q[+el.dataset.i].correct=+e.target.dataset.c};\n box.onclick=e=>{const b=e.target.closest('button'),el=b?.closest('.q');if(!el)return;const q=Q[+el.dataset.i];if('del'in b.dataset)Q.splice(+el.dataset.i,1);else if('addo'in b.dataset)q.options.push('');else if(b.dataset.rm!==undefined)q.options.splice(+b.dataset.rm,1);else return;draw()};\n if(!locked){$('#addmc').onclick=()=>{Q.push({type:'mc',text:'',points:1,options:['','','',''],correct:null});draw()};$('#addtf').onclick=()=>{Q.push({type:'tf',text:'',points:1,options:['صح','خطأ'],correct:null});draw()};$('#addorder').onclick=()=>{Q.push({type:'order',text:'',points:1,options:['','',''],correct:null});draw()}}\n $('#img').onchange=async e=>{try{z.image=await readImg(e.target.files[0]);$('#coverPreview').innerHTML=z.image?`<img src=\"${z.image}\" style=\"max-height:100px\">`:''}catch(x){toast(x.message)}};\n $('#prev').onclick=()=>{step=Math.max(0,step-1);show()};$('#next').onclick=()=>{if(step===0&&!$('#title').value.trim())return toast('اكتب اسم المسابقة أولًا');step=Math.min(2,step+1);show()};\n $('#readSheet').onclick=async()=>{const f=$('#sheet').files[0];if(!f)return toast('اختر صورة الورقة');try{const image=await readImg(f);$('#aiStatus').textContent='جارٍ تحليل الصورة...';const r=await api('/api/ai/parse-sheet','POST',{image});Q.push(...r.questions);draw();$('#aiStatus').textContent='استخرجنا '+r.questions.length+' سؤال. راجع الإجابات قبل الحفظ.'}catch(e){$('#aiStatus').textContent=e.message;toast(e.message)}};\n $('#save').onclick=async()=>{const body={title:$('#title').value,description:$('#desc').value,image:z.image,time_limit:$('#tl').value,start_at:toMs($('#sa').value),end_at:toMs($('#ea').value),shuffle_q:$('#shuffle_q').checked,shuffle_a:$('#shuffle_a').checked,show_correct:$('#show_correct').checked,allow_retry:$('#allow_retry').checked,participation_mode:$('#participation_mode').value,entry_mode:$('#entry_mode').value,progression_mode:$('#progression_mode').value,roster:$('#roster').value,questions:Q};try{if(id)await api('/api/quizzes/'+id,'PUT',body);else{if(!Q.length)throw Error('أضف سؤالًا واحدًا على الأقل');await api('/api/quizzes','POST',body)}toast('تم الحفظ');location.hash='#/quizzes'}catch(e){$('#e').textContent=e.message}};\n}\nasync function results(M,id){const r=await api(`/api/quizzes/${id}/results`),z=r.quiz;\n M.innerHTML=`<div class=row><h1 class=sp>نتائج: ${esc(z.title)}</h1><a class=\"btn p\" target=_blank href=\"/board/${z.code}\">ابدأ المسابقة</a>${r.progression_mode==='teacher'?'<button class=\"btn p\" id=\"unlockNext\">فتح السؤال التالي للمشاركين</button>':''}<a class=\"btn p\" href=\"/api/quizzes/${id}/export.csv\">تصدير CSV</a></div>\n <div class=row><button class=btn id=hide>إخفاء النتائج عن الشاشة</button><button class=btn id=show>إظهار النتائج</button></div>\n <div class=grid style=\"margin:1em 0\"><div class=\"card stat\"><b>${r.rows.length}</b><span>مجموعة</span></div><div class=\"card stat\"><b>${r.avg}/${r.totalPoints}</b><span>متوسط الدرجات</span></div>\n <div class=\"card stat\"><b>${r.hardest?esc(r.hardest.text.slice(0,30)):'—'}</b><span>أصعب سؤال${r.hardest?` (${r.hardest.pct}% صحيح)`:''}</span></div><div class=\"card stat\"><b>${r.easiest?esc(r.easiest.text.slice(0,30)):'—'}</b><span>أسهل سؤال${r.easiest?` (${r.easiest.pct}% صحيح)`:''}</span></div></div>\n <div class=card style=\"overflow-x:auto\"><h2>ترتيب المجموعات</h2><table><tr><th>المركز<th>المجموعة<th>الدرجة<th>صحيحة<th>خاطئة<th>النسبة<th>الوقت<th>الحالة<th></tr>${r.rows.map(x=>`<tr><td>${x.rank}${x.tie?' <span class=tag>تعادل</span>':''}<td>${esc(x.name)}<td>${x.score}/${r.totalPoints}<td>${x.correct}<td>${x.answered-x.correct}<td>${x.answered?Math.round(100*x.correct/x.answered):0}%<td>${dur(x.duration)}<td>${x.done?'أنهت':'تلعب'}<td><button class=\"btn s d\" data-g=${x.id}>حذف</button></tr>`).join('')||'<tr><td colspan=9>لا توجد مجموعات بعد</tr>'}</table></div>\n <div class=card style=\"margin-top:1em;overflow-x:auto\"><h2>تحليل الأسئلة</h2><table><tr><th>السؤال<th>صحيحة<th>خاطئة<th>نسبة الصحة</tr>${r.questions.map(x=>`<tr><td>${esc(x.text.slice(0,60))}${r.mostMissed.some(m=>m.id===x.id)?' <span class=tag>أخطأت فيه معظم المجموعات</span>':''}<td>${x.correct}<td>${x.wrong}<td>${x.pct===null?'—':x.pct+'%'}</tr>`).join('')}</table></div>`;\n const st=s=>async()=>{await api(`/api/quizzes/${id}/board`,'POST',{state:s});toast(s==='hidden'?'أُخفيت النتائج':'أُظهرت النتائج')};if(r.progression_mode==='teacher')$('#unlockNext').onclick=async()=>{try{await api(`/api/quizzes/${id}/unlock`,'POST',{});toast('تم فتح السؤال التالي')}catch(e){toast(e.message)}};$('#hide').onclick=st('hidden');$('#show').onclick=st('shown');\n M.onclick=async e=>{const b=e.target.closest('[data-g]');if(b&&await confirmBox('حذف هذه المجموعة ونتائجها؟')){await api('/api/groups/'+b.dataset.g,'DELETE');results(M,id)}}}\nrender();\n","/style.css":"@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;700&display=swap');\n:root{--ink:#12263A;--mut:#5B6B7B;--bg:#F2F5F8;--card:#fff;--line:#DDE4EB;--g:#0E7C5A;--g2:#0A5C43;--gold:#F2B705;--red:#C23A3A;--ok:#1E8E5A;--r:12px}\n@media(prefers-color-scheme:dark){:root{--ink:#E8EEF4;--mut:#9AABBB;--bg:#0F1A24;--card:#16242F;--line:#27394A}}\n*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}\nbody{margin:0;font:16px/1.7 'IBM Plex Sans Arabic',Tahoma,sans-serif;color:var(--ink);background:var(--bg)}\nh1,h2,h3{line-height:1.3;margin:.2em 0 .5em}a{color:var(--g)}\nbutton,input,select,textarea{font:inherit;color:inherit}\n.btn{display:inline-flex;align-items:center;gap:.4em;border:1px solid var(--line);background:var(--card);padding:.5em 1em;border-radius:10px;cursor:pointer;text-decoration:none;min-height:44px}\n.btn:hover{border-color:var(--g)}.btn.p{background:var(--g);border-color:var(--g);color:#fff}.btn.p:hover{background:var(--g2)}.btn.d{color:var(--red)}.btn.s{min-height:36px;padding:.2em .7em;font-size:.9em}\n:focus-visible{outline:3px solid var(--gold);outline-offset:2px}\ninput,select,textarea{width:100%;padding:.55em .8em;border:1px solid var(--line);border-radius:10px;background:var(--card)}\nlabel{display:block;font-weight:500;margin:.8em 0 .2em}\n.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:1.1em 1.3em}\n.wrap{max-width:1100px;margin:0 auto;padding:1em}\n.nav{background:var(--g2);color:#fff;position:sticky;top:0;z-index:5}.nav .wrap{display:flex;gap:.3em;align-items:center;flex-wrap:wrap;padding:.5em 1em}\n.nav a{color:#fff;text-decoration:none;padding:.4em .9em;border-radius:8px}.nav a.on,.nav a:hover{background:rgba(255,255,255,.18)}.nav b{font-size:1.3em;margin-inline-end:1em}\n.grid{display:grid;gap:1em;grid-template-columns:repeat(auto-fit,minmax(200px,1fr))}\n.stat b{display:block;font-size:2em;line-height:1.2}.stat span{color:var(--mut)}\ntable{width:100%;border-collapse:collapse}th,td{text-align:right;padding:.55em .7em;border-bottom:1px solid var(--line)}th{color:var(--mut);font-weight:500}\n.row{display:flex;gap:.6em;align-items:center;flex-wrap:wrap}.sp{flex:1}\n.tag{display:inline-block;padding:0 .7em;border-radius:99px;background:var(--line);font-size:.85em}\n.q{border:1px solid var(--line);border-radius:var(--r);padding:1em;margin:.8em 0;background:var(--card)}.q.over{border-color:var(--g);border-style:dashed}\n.handle{cursor:grab;color:var(--mut);font-size:1.3em;user-select:none}\n.opt{display:flex;gap:.5em;align-items:center;margin:.3em 0}.opt input[type=radio]{width:auto}\n.err{color:var(--red);min-height:1.5em}\n.toast{position:fixed;bottom:1em;left:50%;transform:translateX(-50%);background:var(--ink);color:var(--bg);padding:.6em 1.2em;border-radius:10px;z-index:99}\ndialog{border:1px solid var(--line);border-radius:var(--r);background:var(--card);color:var(--ink);max-width:min(92vw,420px)}\n.center{min-height:100vh;display:grid;place-items:center;padding:1em}.narrow{width:min(100%,440px)}\n.bar{height:10px;border-radius:9px;background:var(--line);overflow:hidden}.bar i{display:block;height:100%;background:var(--g);transition:width .4s}\n@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}\n\n/* Entrit ownership card */\n.brand-mark{width:40px;height:40px;flex:0 0 40px;margin-inline-start:auto;border:1px solid rgba(255,255,255,.65);border-radius:11px;display:grid;place-items:center;background:rgba(255,255,255,.13);color:#fff;font:700 22px/1 Arial,sans-serif;cursor:pointer;transition:background .18s,transform .18s}\n.brand-mark:hover{background:rgba(255,255,255,.24);transform:translateY(-1px)}\n.brand-dialog{width:min(92vw,390px);max-width:390px;padding:0;border:1px solid var(--line);border-radius:18px;background:var(--card);color:var(--ink);box-shadow:0 18px 55px #0003}\n.brand-dialog::backdrop{background:rgba(5,18,28,.58);backdrop-filter:blur(3px)}\n.brand-card{display:flex;align-items:center;gap:16px;padding:24px 22px}\n.brand-card img{width:84px;height:84px;flex:0 0 84px;object-fit:contain;border-radius:14px;background:var(--bg);padding:7px}\n.brand-copy{display:flex;flex-direction:column;gap:5px;min-width:0}\n.brand-copy strong{font-size:1.15em;color:var(--ink)}\n.brand-copy span{font-size:.88em;color:var(--mut);line-height:1.5}\n.brand-close{display:flex;margin:0 22px 20px auto;min-width:90px;justify-content:center}\n@media(max-width:520px){.brand-card{padding:20px 16px;gap:12px}.brand-card img{width:70px;height:70px;flex-basis:70px}}\n\n.login-card{display:flex;flex-direction:column;gap:1em;text-align:center;padding:2em}\n.login-card p{color:var(--mut);margin:0}\n.login-card small{color:var(--mut)}\n.google-login{justify-content:center;gap:.8em;min-height:50px;font-weight:700}\n.google-login span{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:#fff;color:#4285f4;font:bold 16px Arial}\n.nav-logout{min-height:36px;padding:.25em .75em;background:transparent;color:#fff;border-color:#ffffff55}\n.brand-copy small{color:var(--mut);font-size:.82em;margin-top:3px}\n\n/* مِضمار Cloudflare v2 — واجهة محسّنة */\n:root{color-scheme:light;--ink:#172a36;--mut:#647582;--bg:#f3f7f6;--card:#fff;--line:#dbe6e2;--g:#087f63;--g2:#075b49;--gold:#e5a900;--red:#c43c4a;--ok:#17865d;--r:18px}\nbody{background:radial-gradient(ellipse at 88% 0%,#dcefe8 0,transparent 34%),var(--bg);color:var(--ink)}\n.nav{background:rgba(7,91,73,.97);backdrop-filter:blur(12px);box-shadow:0 8px 28px #062b201c}\n.nav .wrap{max-width:1320px;min-height:68px;gap:.45em;padding:.65em 1.25em}\n.nav b{font-size:1.5em;letter-spacing:-.04em;margin-inline-end:1.2em}\n.nav a{padding:.55em 1em;border-radius:12px;font-weight:600;transition:background .18s,transform .18s}\n.nav a:hover{transform:translateY(-1px)}\n#main{max-width:1320px;padding:1.6em 1.4em 4em}\nh1{font-size:clamp(1.65rem,2.4vw,2.25rem);font-weight:800;letter-spacing:-.035em}\nh2{font-size:1.28rem;font-weight:750}\n.card{border-radius:20px;border-color:#dce8e3;box-shadow:0 8px 28px #173f3010;padding:1.35em 1.5em}\n.grid{gap:1em}\n.stat{position:relative;overflow:hidden;min-height:126px;display:flex;flex-direction:column;justify-content:center;gap:.4em}\n.stat:after{content:\"\";position:absolute;width:90px;height:90px;border-radius:50%;background:#0c8d6b0c;left:-24px;bottom:-30px}\n.stat b{font-size:2.3em;color:var(--g);font-variant-numeric:tabular-nums}\n.stat span{font-size:.94em;font-weight:600}\n.btn{border-radius:12px;padding:.58em 1.05em;font-weight:650;transition:transform .16s,box-shadow .16s,border-color .16s}\n.btn:hover{transform:translateY(-1px);box-shadow:0 5px 16px #143f3014}\n.btn.p{box-shadow:0 5px 14px #087f6324}\ninput,select,textarea{border-radius:12px;min-height:46px;border-color:#d4e0db;background:#fff}\ntextarea{line-height:1.8}\nlabel{font-weight:650;color:#435660}\n.q{border-radius:18px;border-color:#dce8e3;padding:1.2em}\n.tag{background:#e6f3ee;color:#126b55;font-weight:650;padding:.2em .8em}\n.nav-logout{border-radius:10px}\n.brand-mark{border-radius:13px}\n.login-card{border:1px solid #dce8e3;box-shadow:0 18px 50px #163f3017}\n.toast{box-shadow:0 10px 30px #0002}\ndialog{box-shadow:0 20px 65px #0b322333}\n@media(max-width:700px){.nav .wrap{gap:.3em;overflow-x:auto;flex-wrap:nowrap}.nav b{margin-inline-end:.5em;white-space:nowrap}.nav a{white-space:nowrap;padding:.45em .7em;font-size:.93em}.nav-logout{white-space:nowrap}#main{padding:1.1em .8em 3em}.card{padding:1.05em}.row>.sp{min-width:100%}}\n","/board.html":"<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>لوحة المسابقة – مِضمار</title><link rel=\"stylesheet\" href=\"/style.css\">\n<style>\n:root{color-scheme:dark}\nbody{background:#09271f;color:#fff;min-height:100vh;overflow-x:hidden}\n.hd{display:flex;align-items:center;gap:1em;padding:1em 2vw;border-bottom:1px solid #ffffff20}\n.hd h1{margin:0;font-size:clamp(1.4rem,3vw,2.6rem)}\n.hd .spacer{flex:1}\n.hd .btn{background:#ffffff12;color:#fff;border-color:#ffffff35}\n.stats{display:flex;gap:1.5em;padding:.8em 2vw;color:#bfe3d5;font-size:clamp(.95rem,1.5vw,1.3rem);flex-wrap:wrap}\n.stage{padding:2vh 2vw 4vh;display:grid;grid-template-columns:minmax(0,1fr);gap:2vw;align-items:start}.stage.has-completed{grid-template-columns:minmax(190px,260px) minmax(0,1fr)}\n.qr-card,.results-card{background:#ffffff0c;border:1px solid #ffffff20;border-radius:20px;padding:1.2em}\n.qr-card{text-align:center;position:sticky;top:1em}\n.qr-card img{display:block;width:min(100%,340px);aspect-ratio:1;object-fit:contain;background:#fff;border-radius:12px;padding:10px;margin:.8em auto}\n.qr-card.compact img{width:min(100%,150px)}.qr-card.compact{padding:.8em}.qr-card .code{font-size:1.5em;font-weight:700;letter-spacing:.12em;color:#f2b705}\n.qr-card p{margin:.25em 0;color:#c6ddd5}\n.results-card{min-height:300px}\n.waiting{text-align:center;padding:6vh 1em}\n.waiting h2{font-size:clamp(1.5rem,3vw,2.8rem);color:#f2b705}\n.waiting p{color:#c6ddd5;font-size:1.1rem}\n.first{border:1px solid #f2b70570;background:linear-gradient(135deg,#f2b70524,#ffffff08);border-radius:16px;padding:1em;margin-bottom:1em}\n.first small{color:#f2b705;font-weight:700}\n.first strong{display:block;font-size:clamp(1.5rem,3vw,2.4rem);margin:.25em 0}\n.first .time{color:#c6ddd5}\n.rank-list{display:grid;gap:.6em}\\n.progress-wrap{background:#ffffff0c;border:1px solid #ffffff20;border-radius:16px;padding:1em;margin-bottom:1em}.progress-table{border-collapse:collapse;width:100%;min-width:420px;text-align:center}.progress-table th,.progress-table td{padding:.65em;border-bottom:1px solid #ffffff20}.progress-table th:first-child{text-align:right;min-width:130px}.progress-table td{color:#f2b705;font-weight:800}.progress-table td:has(+td){ }\n.rank-row{display:flex;align-items:center;gap:.8em;background:#ffffff0c;border:1px solid #ffffff12;border-radius:12px;padding:.75em 1em;font-size:clamp(.95rem,1.5vw,1.25rem)}\n.rank-row.top{border-color:#f2b70580;background:#f2b70517}\n.rank{width:2em;font-weight:800;color:#f2b705}\n.team{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.score{font-weight:700;white-space:nowrap}\n.meta{color:#b7ccc4;font-size:.88em;white-space:nowrap}\n.active{margin-top:1.2em;color:#b7ccc4}\n.active summary{cursor:pointer;padding:.5em}\n.active-list{display:flex;flex-wrap:wrap;gap:.5em;padding:.5em}\n.active-list span{background:#ffffff12;border-radius:99px;padding:.2em .8em}\n.brand-mark{margin-inline-start:0;width:46px;height:46px;flex-basis:46px}\ncanvas{position:fixed;inset:0;pointer-events:none;z-index:9}\n@media(max-width:760px){.stage,.stage.has-completed{grid-template-columns:1fr}.qr-card{position:static;order:0}.results-card{order:1}.qr-card img{width:190px}}\n</style></head>\n<body>\n<header class=\"hd\"><h1 id=\"title\">مِضمار – لوحة المسابقة</h1><span class=\"spacer\"></span><button class=\"btn\" id=\"fs\">ملء الشاشة</button><span class=\"brand-mark\" title=\"حقوق إنتريت\" aria-label=\"حقوق إنتريت\"><img src=\"/entrit-logo.svg\" alt=\"إنتريت\"></span></header>\n<div class=\"stats\"><span id=\"joined\">الفرق المشاركة: 0</span><span id=\"finished\">أنهت المسابقة: 0</span><span id=\"playing\">تلعب الآن: 0</span></div>\n<main class=\"stage\">\n<aside class=\"qr-card\" id=\"qr-card\"><h2>امسح رمز QR للانضمام</h2><img id=\"qr\" alt=\"رمز الانضمام\"><div class=\"code\" id=\"code\"></div><p>افتح كاميرا الجوال وامسح الرمز</p><p id=\"join-url\" style=\"font-size:.8em;overflow-wrap:anywhere\"></p></aside>\n<section class=\"results-card\" id=\"results\"><div class=\"waiting\"><h2>بانتظار الفرق</h2><p>امسحوا رمز QR للانضمام إلى المسابقة</p></div></section>\n</main><canvas id=\"confetti\"></canvas>\n\n<script>\nconst code=location.pathname.split('/').pop(),$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst duration=s=>{s=Math.max(0,Number(s)||0);return s>=60?Math.floor(s/60)+'د '+String(s%60).padStart(2,'0')+'ث':s+'ث'};\nconst joinUrl=location.origin+'/j/'+encodeURIComponent(code);\n$('qr').src='/api/qr?text='+encodeURIComponent(joinUrl);$('code').textContent=code;$('join-url').textContent=joinUrl;\n$('fs').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();\nlet lastBoard='';async function refreshBoard(){try{const r=await fetch('/api/board/'+encodeURIComponent(code),{cache:'no-store'});if(!r.ok)return;const d=await r.json();const sig=JSON.stringify(d);if(sig!==lastBoard){lastBoard=sig;draw(d)}}catch(e){console.warn('تعذر تحديث اللوحة',e)}}refreshBoard();setInterval(refreshBoard,1200);\nlet announced=null;\nfunction progressMatrix(d){if(!d.rows?.length)return '<div class=\"waiting\"><p>لا يوجد مشاركون حتى الآن.</p></div>';const qs=d.questions||[];return `<div class=\"progress-wrap\"><h2>متابعة تقدم المشاركين</h2><div style=\"overflow:auto\"><table class=\"progress-table\"><thead><tr><th>المشارك</th>${qs.map((q,i)=>`<th>س${i+1}</th>`).join('')}</tr></thead><tbody>${d.rows.map(r=>`<tr><th>${esc(r.name)}</th>${(r.progress||[]).map(p=>`<td title=\"${p.status==='done'?'مكتمل':p.status==='active'?'قيد التنفيذ':'لم يبدأ'}\">${p.status==='done'?'✓':p.status==='active'?'◉':'·'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class=\"meta\">✓ مكتمل · ◉ قيد التنفيذ · · لم يبدأ</p></div>`}\nfunction draw(d){\n $('title').textContent='مِضمار – '+d.title;\n $('joined').textContent='الفرق المشاركة: '+(d.rows?.length||0);\n $('finished').textContent='أنهت المسابقة: '+d.finished;\n $('playing').textContent='تلعب الآن: '+d.playing;\n const completed=(d.rows||[]).filter(r=>r.done).sort((a,b)=>b.score-a.score||a.duration-b.duration||a.id-b.id);\n const active=(d.rows||[]).filter(r=>!r.done);\n const qr=$('qr-card'),stage=document.querySelector('.stage');\n if(!completed.length){\n  stage.classList.remove('has-completed');qr.classList.remove('compact');\n  $('results').innerHTML=progressMatrix(d)+'<div class=\"waiting\"><h2>بانتظار اكتمال المشاركين</h2><p>تظهر حالة الإجابة لكل مشارك مباشرة عند إرسالها.</p><p>المشاركون: <b>'+((d.rows||[]).length)+'</b></p></div>';\n  return;\n }\n stage.classList.add('has-completed');qr.classList.add('compact');\n if(d.hidden){$('results').innerHTML=progressMatrix(d)+'<div class=\"waiting\"><h2>الترتيب مخفي مؤقتًا</h2><p>متابعة تقدم المشاركين ما زالت ظاهرة.</p></div>';return;}\n const first=[...completed].sort((a,b)=>(a.finishedAt||Number.MAX_SAFE_INTEGER)-(b.finishedAt||Number.MAX_SAFE_INTEGER))[0]||completed[0];\n const rows=completed.map((r,i)=>'<div class=\"rank-row '+(i===0?'top':'')+'\"><span class=\"rank\">'+(i===0?'🥇':i===1?'🥈':i===2?'🥉':(i+1))+'</span><span class=\"team\">'+esc(r.name)+'</span><span class=\"score\">'+r.score+'/'+d.totalPoints+'</span><span class=\"meta\">'+duration(r.duration)+'</span></div>').join('');\n const activeHtml=active.length?'<details class=\"active\"><summary>فرق لم تنه الإجابة بعد ('+active.length+')</summary><div class=\"active-list\">'+active.map(r=>'<span>'+esc(r.name)+'</span>').join('')+'</div></details>':'';\n $('results').innerHTML=progressMatrix(d)+'<div class=\"first\"><small>اكتمل المشارك الأول</small><strong>'+esc(first.name)+'</strong><span class=\"time\">الدرجة '+first.score+'/'+d.totalPoints+' · الزمن '+duration(first.duration)+'</span></div><h2>ترتيب الفرق المكتملة</h2><div class=\"rank-list\">'+rows+'</div>'+activeHtml;\n const signature=first.id+':'+first.score+':'+first.duration;\n if(active.length===0&&announced!==signature){announced=signature;confetti()}\n}\nfunction confetti(){\n if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;\n const c=$('confetti'),ctx=c.getContext('2d');c.width=innerWidth;c.height=innerHeight;\n const colors=['#f2b705','#fff','#1fbf8f','#e8643c'];\n const parts=Array.from({length:140},()=>({x:Math.random()*c.width,y:-20-Math.random()*c.height*.4,v:2+Math.random()*4,r:4+Math.random()*6,color:colors[Math.random()*colors.length]}));\n let frame=0;(function animate(){ctx.clearRect(0,0,c.width,c.height);for(const p of parts){p.y+=p.v;ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.r,p.r*1.6)}if(++frame<180)requestAnimationFrame(animate);else ctx.clearRect(0,0,c.width,c.height)})();\n}\n</script></body></html>","/play.html":"<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>مِضمار</title><link rel=\"stylesheet\" href=\"/style.css\">\n<style>body{-webkit-user-select:none;user-select:none}.top{background:var(--g2);color:#fff;padding:.6em 1em}.top .bar{background:rgba(255,255,255,.25)}.top .bar i{background:var(--gold)}\n.choice{display:block;width:100%;text-align:right;font-size:1.15em;padding:.9em 1em;margin:.5em 0;border:2px solid var(--line);border-radius:14px;background:var(--card);cursor:pointer;min-height:56px}\n.choice.sel{border-color:var(--g);background:rgba(14,124,90,.12)}.choice.right{border-color:var(--ok);background:rgba(30,142,90,.2)}.choice.wrong{border-color:var(--red);background:rgba(194,58,58,.15)}\n.big{font-size:3em;font-weight:700;line-height:1.1}.fb{padding:.6em 1em;border-radius:10px;margin:.6em 0;font-weight:700}.fb.ok{background:rgba(30,142,90,.2)}.fb.no{background:rgba(194,58,58,.15)}</style></head><body><div id=app></div>\n<script>\nconst code=location.pathname.split('/').pop(),KEY='mid_'+code,app=document.getElementById('app');let token=localStorage.getItem(KEY),S=null,sel=null,orderSel=[],busy=false,timer=null,waitTimer=null,off=0;\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nasync function api(u,m='GET',b){const r=await fetch(u,{method:m,headers:b?{'Content-Type':'application/json'}:{},body:b?JSON.stringify(b):undefined});const j=await r.json().catch(()=>({}));if(!r.ok){const e=Error(j.error||'حدث خطأ');e.data=j;throw e}return j}\nasync function start(){if(token){try{S=await api('/api/play/'+token);off=S.now-Date.now();return game()}catch(e){localStorage.removeItem(KEY);token=null}}\n try{const i=await api('/api/join/'+code);intro(i)}catch(e){app.innerHTML=`<div class=center><div class=\"card narrow\"><h2>تعذّر فتح المسابقة</h2><p>${esc(e.message)}</p></div></div>`}}\nfunction intro(i){const student=i.participation_mode==='students',roster=i.roster||[];app.innerHTML=`<div class=center><div class=\"card narrow\"><h1>${esc(i.title)}</h1>${i.image?`<img src=\"${i.image}\" alt=\"\" style=\"max-width:100%;border-radius:10px\">`:''}<p>${esc(i.description)}</p>\n <p class=tag>${i.nq} سؤال${i.time_limit?` · ${i.time_limit} دقيقة`:''}</p><p>${student?'مشاركة فردية – كل طالب يشارك من جهازه.':'مشاركة جماعية – جوال واحد لكل مجموعة.'}</p>\n ${i.status==='open'?`${student&&i.entry_mode!=='qr'&&roster.length?`<label for=roster>اختر اسمك من قائمة المعلم</label><select id=roster><option value=\"\">اختيار الاسم</option>${roster.map(x=>`<option value=\"${x.id}\">${esc(x.name)}</option>`).join('')}</select>`:''}${!student||i.entry_mode!=='roster'?`<label for=n>${student?'اسم الطالب':'اسم المجموعة'}</label><input id=n maxlength=40 autocomplete=off>`:''}<p class=err id=e></p><button class=\"btn p\" id=go style=\"width:100%;justify-content:center\">${student?'ابدأ المشاركة':'ابدئي المسابقة'}</button>`:`<p class=err>المسابقة ${esc(i.status)}</p>`}</div></div>`;\n const go=document.getElementById('go');if(go)go.onclick=async()=>{go.disabled=true;try{const payload={name:document.getElementById('n')?.value,roster_id:document.getElementById('roster')?.value};const r=await api('/api/join/'+code,'POST',payload);token=r.token;localStorage.setItem(KEY,token);S=await api('/api/play/'+token);off=S.now-Date.now();game()}catch(e){document.getElementById('e').textContent=e.message;go.disabled=false}}}\nfunction game(){clearInterval(timer);clearInterval(waitTimer);if(S.done)return end();if(S.waiting){app.innerHTML=`<div class=center><div class=\"card narrow\" style=\"text-align:center\"><h2>بانتظار المعلم</h2><p>أكملت السؤال المتاح. سيظهر السؤال التالي هنا عند فتحه من لوحة المعلم.</p><div class=tag>لا تغلق الصفحة</div></div></div>`;waitTimer=setInterval(async()=>{try{S=await api('/api/play/'+token);off=S.now-Date.now();if(!S.waiting)game()}catch(e){}},1500);return}sel=null;busy=false;const q=S.question;orderSel=q.type==='order'?q.options.map(x=>x.i).sort(()=>Math.random()-.5):[];\n app.innerHTML=`<div class=top><div class=row><b>${esc(S.title)}</b><span class=sp></span><span id=tm></span></div><div class=row><small>${esc(S.group)}</small><span class=sp></span><small>سؤال ${S.answered+1} من ${S.total}</small></div><div class=bar style=\"margin-top:.4em\"><i style=\"width:${100*S.answered/S.total}%\"></i></div></div>\n <div class=wrap style=\"max-width:640px\"><h2 style=\"margin-top:.8em\">${esc(q.text)}</h2>${q.image?`<img src=\"${q.image}\" alt=\"\" style=\"max-width:100%;border-radius:10px\">`:''}<div id=ch>${q.type==='order'?orderSel.map((n,i)=>`<div class=choice style=\"display:flex;align-items:center;gap:.5em\"><b>${i+1}.</b><span class=sp>${esc(q.options.find(x=>x.i===n).t)}</span><button class=\"btn s\" data-move=\"up\" data-pos=${i} ${i===0?'disabled':''}>↑</button><button class=\"btn s\" data-move=\"down\" data-pos=${i} ${i===orderSel.length-1?'disabled':''}>↓</button></div>`).join(''):` ${q.options.map(o=>`<button class=choice data-i=${o.i}>${esc(o.t)}</button>`).join('')}`}</div><div id=fb></div>\n <button class=\"btn p\" id=ok disabled style=\"width:100%;justify-content:center;font-size:1.1em\">تأكيد الإجابة</button></div>`;\n if(S.progression_mode==='free'){api('/api/play/'+token+'/questions').then(d=>{const nav=document.createElement('div');nav.className='card';nav.style.cssText='display:flex;gap:.4em;flex-wrap:wrap;margin:1em 0';nav.innerHTML='<b style=\"width:100%\">اختر السؤال:</b>'+d.questions.map(q=>`<button class=\"btn ${q.answered?'s':'p'}\" ${q.answered?'disabled':''} data-q=\"${q.id}\">سؤال ${q.index}</button>`).join('');app.querySelector('.wrap').prepend(nav);nav.onclick=async e=>{const btn=e.target.closest('[data-q]');if(!btn)return;try{S=await api('/api/play/'+token+'?question_id='+btn.dataset.q);game()}catch(err){console.warn(err)}}}).catch(()=>{})}\n document.getElementById('ch').onclick=e=>{if(busy)return;const mv=e.target.closest('[data-move]');if(mv){const p=+mv.dataset.pos,to=mv.dataset.move==='up'?p-1:p+1;if(to>=0&&to<orderSel.length){[orderSel[p],orderSel[to]]=[orderSel[to],orderSel[p]];gameOrderDraw(q)}return}const b=e.target.closest('.choice[data-i]');if(!b)return;sel=+b.dataset.i;document.querySelectorAll('.choice').forEach(x=>x.classList.toggle('sel',x===b));document.getElementById('ok').disabled=false};\n document.getElementById('ok').onclick=submit;if(q.type==='order'){document.getElementById('ok').disabled=false;window.gameOrderDraw=gameOrderDraw}tick();if(S.deadline)timer=setInterval(tick,500)}\nfunction gameOrderDraw(q){const box=document.getElementById('ch');if(!box)return;box.innerHTML=orderSel.map((n,i)=>`<div class=choice style=\"display:flex;align-items:center;gap:.5em\"><b>${i+1}.</b><span class=sp>${esc(q.options.find(x=>x.i===n).t)}</span><button class=\"btn s\" data-move=\"up\" data-pos=${i} ${i===0?'disabled':''}>↑</button><button class=\"btn s\" data-move=\"down\" data-pos=${i} ${i===orderSel.length-1?'disabled':''}>↓</button></div>`).join('')}\nfunction tick(){if(!S.deadline)return;const t=Math.max(0,Math.ceil((S.deadline-(Date.now()+off))/1000)),el=document.getElementById('tm');if(el)el.textContent=`${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;\n if(t<=0){clearInterval(timer);api('/api/play/'+token).then(s=>{S=s;if(s.done)end()})}}\nasync function submit(){if(sel===null||busy)return;busy=true;const btn=document.getElementById('ok');btn.disabled=true;\n try{const r=await api('/api/play/'+token+'/answer','POST',S.question.type==='order'?{question_id:S.question.id,order:orderSel}:{question_id:S.question.id,choice:sel});S=r.state;\n  if(r.correct===null)return game();if(S.question?.type!=='order')document.querySelectorAll('.choice[data-i]').forEach(x=>{const i=+x.dataset.i;if(i===r.right)x.classList.add('right');else if(i===sel)x.classList.add('wrong')});\n  document.getElementById('fb').innerHTML=`<div class=\"fb ${r.correct?'ok':'no'}\">${r.correct?'إجابة صحيحة!':'إجابة خاطئة'}</div>`;btn.textContent='السؤال التالي';btn.disabled=false;btn.onclick=game}\n catch(e){if(e.data?.state){S=e.data.state;return game()}busy=false;btn.disabled=false;document.getElementById('fb').innerHTML=`<p class=err>${esc(e.message)}</p>`}}\nfunction end(){clearInterval(timer);const m=Math.floor(S.duration/60),s=S.duration%60;app.innerHTML=`<div class=center><div class=\"card narrow\" style=\"text-align:center\"><h1>انتهت المسابقة</h1><p>${esc(S.group)}</p><div class=big>${S.score}<small style=\"font-size:.4em;color:var(--mut)\"> / ${S.totalPoints}</small></div>\n <p>${S.correct} إجابة صحيحة من ${S.total} · الوقت ${m}د ${s}ث</p>${S.rank?`<p class=tag>مركزكم الحالي: ${S.rank}</p>`:''}<p>تابعي لوحة المتصدرات على شاشة الفصل.</p>${S.retry?'<button class=\"btn p\" id=rt>إعادة المحاولة</button>':''}</div></div>`;\n const r=document.getElementById('rt');if(r)r.onclick=async()=>{await api('/api/play/'+token+'/retry','POST');S=await api('/api/play/'+token);off=S.now-Date.now();game()}}\nstart();\n</script></body></html>\n","/entrit-logo.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 256 314\"><image width=\"256\" height=\"314\" href=\"data:image/png;base64,\"/></svg>"};
